import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.CWpttWmj.js";const k=JSON.parse('{"title":"Fees","description":"","frontmatter":{},"headers":[],"relativePath":"protocol/fees.md","filePath":"protocol/fees.md","lastUpdated":null}'),r={name:"protocol/fees.md"};function n(o,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="fees" tabindex="-1">Fees <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;Fees&quot;">​</a></h1><p>Three separate costs appear when using Arc Names, and they go to three different places. Keeping them distinct avoids a lot of confusion.</p><table tabindex="0"><thead><tr><th>Cost</th><th>Paid to</th><th>When</th></tr></thead><tbody><tr><td><strong>Registration / renewal price</strong></td><td>The protocol (controller)</td><td>Registering or renewing a name</td></tr><tr><td><strong>Marketplace fee</strong></td><td>The protocol (market)</td><td>A name sells on the marketplace</td></tr><tr><td><strong>Gas</strong></td><td>Network validators</td><td>Every transaction</td></tr></tbody></table><p>Arc Names takes no cut of a direct transfer between wallets, and no fee for setting records beyond the gas.</p><h2 id="registration-and-renewal" tabindex="-1">Registration and renewal <a class="header-anchor" href="#registration-and-renewal" aria-label="Permalink to &quot;Registration and renewal&quot;">​</a></h2><p>Priced by name length, per year, prorated to the second:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">price</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, dur) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usdPerYear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm).length) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dur </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 365</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> days</span></span></code></pre></div><p>Renewal uses the same tiers as registration — there is no discount and no penalty for renewing. The rates are owner-configurable and this page deliberately doesn&#39;t print them; see <a href="/docs/guide/pricing.html">Pricing &amp; rarity</a> for how to read the live values.</p><p>Proceeds accumulate in the controller and are withdrawn by the contract owner via <code>withdraw</code>.</p><h3 id="overpayment-is-refunded" tabindex="-1">Overpayment is refunded <a class="header-anchor" href="#overpayment-is-refunded" aria-label="Permalink to &quot;Overpayment is refunded&quot;">​</a></h3><p>Both <code>register</code> and <code>renew</code> refund the excess in the same transaction:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> due) { (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ok,) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.call{value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> due}(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ok); }</span></span></code></pre></div><p>Sending a buffer above the quote is therefore safe, and is what the app does so a price change between quote and mint doesn&#39;t revert your transaction. You are never charged the buffer.</p><h2 id="marketplace-fees" tabindex="-1">Marketplace fees <a class="header-anchor" href="#marketplace-fees" aria-label="Permalink to &quot;Marketplace fees&quot;">​</a></h2><p>Deducted from the <strong>seller&#39;s</strong> proceeds, not added to the buyer&#39;s price:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buyer pays   price</span></span>
<span class="line"><span>seller gets  price − (price × feeBps / 10000)</span></span>
<span class="line"><span>protocol     price × feeBps / 10000</span></span></code></pre></div><p><code>feeBps</code> initialises to <strong>zero</strong>, so unless the owner has changed it the seller receives the full sale price. It is a live value — read <code>feeBps()</code> from the market rather than trusting a number here.</p><p>The fee goes to <code>feeRecipient</code>. If paying the seller fails, their proceeds are credited to a pending balance they can withdraw later, rather than reverting the sale.</p><h2 id="referral-economics" tabindex="-1">Referral economics <a class="header-anchor" href="#referral-economics" aria-label="Permalink to &quot;Referral economics&quot;">​</a></h2><p>Two independent referral systems, both denominated in basis points, both defaulting to zero.</p><h3 id="controller-referrals" tabindex="-1">Controller referrals <a class="header-anchor" href="#controller-referrals" aria-label="Permalink to &quot;Controller referrals&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>due    = base − (base × refDiscountBps / 10000)     // buyer&#39;s discount</span></span>
<span class="line"><span>reward = base × refRewardBps / 10000                // referrer&#39;s payment</span></span></code></pre></div><p>Each rate is capped at 2000 bps (20%). Note that the discount and the reward are <strong>separate</strong> — the reward is not taken out of the discounted price, it is paid on top from protocol revenue. Both come out of what the protocol would otherwise keep.</p><p>A referrer is ignored if it is the zero address, the caller, or the name&#39;s owner — no self-referral.</p><h3 id="market-referrals" tabindex="-1">Market referrals <a class="header-anchor" href="#market-referrals" aria-label="Permalink to &quot;Market referrals&quot;">​</a></h3><p>Constrained so referrals can never eat into seller proceeds:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(discountBps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rewardBps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feeBps, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;exceeds fee&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Referrals are funded entirely from the protocol&#39;s own fee. With <code>feeBps</code> at zero, market referrals are necessarily inert.</p><h3 id="withdrawal-fallback" tabindex="-1">Withdrawal fallback <a class="header-anchor" href="#withdrawal-fallback" aria-label="Permalink to &quot;Withdrawal fallback&quot;">​</a></h3><p>If paying a referrer fails, the amount is credited to <code>pendingWithdrawals[referrer]</code> and claimable with <code>withdrawPending()</code>. The registration still succeeds — a referrer that can&#39;t receive funds never blocks a user&#39;s transaction.</p><h2 id="two-kinds-of-usdc" tabindex="-1">Two kinds of USDC <a class="header-anchor" href="#two-kinds-of-usdc" aria-label="Permalink to &quot;Two kinds of USDC&quot;">​</a></h2><p>This is the single most error-prone detail in the protocol.</p><table tabindex="0"><thead><tr><th></th><th>Native USDC</th><th>ERC-20 USDC</th></tr></thead><tbody><tr><td>What it is</td><td>Arc&#39;s gas token</td><td>A token contract</td></tr><tr><td>Decimals</td><td><strong>18</strong></td><td><strong>6</strong></td></tr><tr><td>Used for</td><td>Gas, and the default payment path</td><td>The alternative payment path</td></tr><tr><td>In the API</td><td><code>priceWei</code>, <code>amountWei</code>, <code>totalRevenueWei</code></td><td><code>currency: 1</code> listings</td></tr></tbody></table><p>The pricing is scaled so <strong>1 USD = 1e18 native wei</strong>, which means <code>price()</code> returns the USD price directly, in wei. The ERC-20 equivalent is the same amount divided by <code>1e12</code>:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">priceUSDC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, dur) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> price</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, dur) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e12</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Getting the decimals wrong is a factor of a trillion</p><p>Formatting an 18-decimal value as 6 decimals — or configuring a wallet&#39;s currency decimals as 6 — makes every price and balance wrong by 1,000,000,000,000×.</p><p>Always format native amounts with 18 decimals. Every <code>*Wei</code> field in the API is 18-decimal native wei, including in listings whose <code>currency</code> is 1.</p></div><h3 id="paying-with-erc-20-usdc" tabindex="-1">Paying with ERC-20 USDC <a class="header-anchor" href="#paying-with-erc-20-usdc" aria-label="Permalink to &quot;Paying with ERC-20 USDC&quot;">​</a></h3><p>The controller offers <code>registerManyUSDC</code> and <code>renewUSDC</code>; the market offers <code>listUSDC</code>. These require the <code>usdc</code> address to be configured — if it&#39;s zero, those calls revert with <code>usdc off</code>.</p><p>ERC-20 payment pulls tokens via <code>transferFrom</code>, so it needs an allowance first, and reverts with <code>usdc pull</code> if the pull fails.</p><p>Listings carry a currency flag: <code>0</code> native, <code>1</code> ERC-20. They are not interchangeable — calling native <code>buy</code> on a USDC listing reverts with <code>usdc listing</code>. The app handles native only.</p><h2 id="gas" tabindex="-1">Gas <a class="header-anchor" href="#gas" aria-label="Permalink to &quot;Gas&quot;">​</a></h2><p>Paid to validators, not to Arc Names, and not something the protocol controls.</p><p>Rough transaction counts, since gas scales with how many transactions a flow needs:</p><table tabindex="0"><thead><tr><th>Action</th><th>Transactions</th></tr></thead><tbody><tr><td>Register a name</td><td>2 (commit + register)</td></tr><tr><td>Renew</td><td>1</td></tr><tr><td>Set one record</td><td>1 per record</td></tr><tr><td>Set primary name</td><td>1</td></tr><tr><td>Transfer</td><td>1, plus 1 for the recipient&#39;s reclaim</td></tr><tr><td>List for sale</td><td>2 (approve + list), or 1 if already approved</td></tr><tr><td>Change listing price</td><td>1</td></tr><tr><td>Buy</td><td>1</td></tr></tbody></table><p>Two ways to spend less gas overall:</p><ul><li><strong>Register for longer.</strong> A 5-year registration costs the same per year as a 1-year one but needs one transaction instead of five renewals.</li><li><strong>Batch registrations.</strong> <code>registerMany</code> handles up to 20 names under one commitment.</li></ul><h2 id="what-has-no-fee" tabindex="-1">What has no fee <a class="header-anchor" href="#what-has-no-fee" aria-label="Permalink to &quot;What has no fee&quot;">​</a></h2><ul><li>Transferring a name directly between wallets (gas only).</li><li>Setting or changing records (gas only).</li><li>Setting a primary name (gas only).</li><li>Reading anything — resolution, availability, the API. All free.</li><li>Renewing someone else&#39;s name. Anyone can renew any name, and it costs only the renewal price.</li></ul><h2 id="where-the-money-goes" tabindex="-1">Where the money goes <a class="header-anchor" href="#where-the-money-goes" aria-label="Permalink to &quot;Where the money goes&quot;">​</a></h2><p>Registration and renewal revenue accumulates in the controller; marketplace fees go to <code>feeRecipient</code>. Both are withdrawn by the contract owner. There is currently no on-chain treasury, no fee-sharing, and no token.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/pricing.html">Pricing &amp; rarity</a> — how the tiers work.</li><li><a href="/docs/guide/marketplace.html">Marketplace</a> — the seller&#39;s side of the fee.</li><li><a href="/docs/protocol/architecture.html">Architecture</a> — which contract holds which parameter.</li></ul>`,52)])])}const g=a(r,[["render",n]]);export{k as __pageData,g as default};
